/* FinTree Explorer v2 — vanilla-JS port of the Claude Design `.dc` prototype
 * (FinTree Explorer v2.dc.html).
 *
 * The prototype ran on a bespoke component runtime (support.js / DCLogic) and
 * read a hand-shaped `window.FINTREE_PL` view-model. To avoid a second data
 * file that would drift from the canonical dataset, this port keeps ONE source
 * of truth — `window.FINTREE_DATA` (234 nodes generated by compile_tree.py) —
 * and derives the shapes the design expects via buildPL() at load time.
 *
 * Three views: Waterfall (illustrative P&L bridge), Hierarchy (icicle of the
 * full ontology), Statement (Reg S-X 5-03 order). A detail panel renders the
 * selected node. Dark/light themes; GSAP enter animations with graceful
 * degradation and prefers-reduced-motion support.
 */
(function () {
  'use strict';

  /* ── Helpers ──────────────────────────────────────────────────────── */
  const esc = (s) => String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  // Serialize a style object (camelCase keys) into a CSS declaration string.
  const st = (o) => {
    if (o == null) return '';
    if (typeof o === 'string') return o;
    let out = '';
    for (const k in o) {
      if (!Object.prototype.hasOwnProperty.call(o, k)) continue;
      const v = o[k];
      if (v == null || v === '') continue;
      out += k.replace(/[A-Z]/g, (m) => '-' + m.toLowerCase()) + ':' + v + ';';
    }
    return out;
  };

  const fmt = (n) => Math.round(n).toLocaleString('en-US');

  /* ── Theme tokens ─────────────────────────────────────────────────── */
  const DARK = { '--bg': '#0E1116', '--bg2': '#11161D', '--panel': '#161C25', '--panel2': '#1C232E', '--line': 'rgba(255,255,255,.08)', '--line2': 'rgba(255,255,255,.15)', '--ink': '#E8EDF3', '--ink2': '#A9B4C0', '--ink3': '#717E8C', '--ink4': '#505D6B', '--c-green': '#34C77B', '--c-red': '#F2696B', '--c-amber': '#E7B35A', '--c-indigo': '#7C9BF5', '--c-slate': '#93A1B0', '--shadow': '0 10px 30px rgba(0,0,0,.35)' };
  const LIGHT = { '--bg': '#F4F6F9', '--bg2': '#FFFFFF', '--panel': '#FFFFFF', '--panel2': '#F6F8FA', '--line': 'rgba(15,23,42,.09)', '--line2': 'rgba(15,23,42,.16)', '--ink': '#0F1B2D', '--ink2': '#48566A', '--ink3': '#6B7888', '--ink4': '#9AA6B4', '--c-green': '#0E9F6E', '--c-red': '#DD4548', '--c-amber': '#B9821A', '--c-indigo': '#3E63DD', '--c-slate': '#5A6675', '--shadow': '0 8px 26px rgba(15,23,42,.09)' };

  const tints = (tone) => {
    const c = `var(--c-${tone})`;
    return { color: c, soft: `color-mix(in srgb, ${c} 18%, transparent)`, tint: `color-mix(in srgb, ${c} 11%, var(--panel))`, border: `color-mix(in srgb, ${c} 30%, var(--line))` };
  };

  const ICON = { revenue: 'R', cogs: 'C', opex: 'O', nonop: 'N', tax: 'T', btl: 'B' };
  const SIGN = { '+': 'Inflow · Credit', '-': 'Outflow · Debit', '±': 'Mixed · ± to result' };

  /* ── Waterfall (illustrative figures; structure from the ontology) ──── */
  const SPINE = [
    { key: 'revenue', label: 'Revenue', src: 'fintree:NetRevenue', type: 'start', tone: 'green', lo: 0, hi: 1000, val: 1000, margin: '100%' },
    { key: 'cogs', label: 'Cost of Rev.', src: 'fintree:CostOfGoodsSoldCostOfRevenue', type: 'delta', tone: 'red', lo: 620, hi: 1000, val: -380 },
    { key: 'grossprofit', label: 'Gross Profit', src: 'fintree:GrossProfit', type: 'total', tone: 'indigo', lo: 0, hi: 620, val: 620, margin: '62.0% margin' },
    { key: 'opex', label: 'Operating Exp.', src: 'fintree:OperatingExpenses', type: 'delta', tone: 'amber', lo: 190, hi: 620, val: -430 },
    { key: 'ebit', label: 'Op. Income', src: 'fintree:OperatingIncome', type: 'total', tone: 'indigo', lo: 0, hi: 190, val: 190, margin: '19.0% margin' },
    { key: 'nonop', label: 'Non-Operating', src: 'fintree:NonoperatingIncomeExpenses', type: 'delta', tone: 'slate', lo: 165, hi: 190, val: -25 },
    { key: 'ebt', label: 'Pre-Tax Inc.', src: 'fintree:PretaxIncome', type: 'total', tone: 'indigo', lo: 0, hi: 165, val: 165, margin: '16.5% margin' },
    { key: 'tax', label: 'Income Tax', src: 'fintree:IncomeTaxExpense', type: 'delta', tone: 'red', lo: 127, hi: 165, val: -38 },
    { key: 'netincome', label: 'Net Income', src: 'fintree:NetIncome', type: 'total', tone: 'green', lo: 0, hi: 127, val: 127, margin: '12.7% margin' },
  ];
  const BD = {
    revenue: [['fintree:GrossRevenue', 'Gross Revenue', 1060, 'green'], ['fintree:RevenueDeductions', 'Revenue Deductions', 60, 'red']],
    cogs: [['fintree:DirectMaterials', 'Direct Materials', 120, 'red'], ['fintree:DirectLabor', 'Direct Labor', 90, 'red'], ['fintree:ServiceDeliveryCosts', 'Service Delivery', 90, 'red'], ['fintree:ManufacturingOverhead', 'Mfg. Overhead', 70, 'red'], ['fintree:InventoryAdjustments', 'Inventory Adj.', 10, 'red']],
    opex: [['fintree:SellingExpenses', 'Selling', 180, 'amber'], ['fintree:ResearchDevelopment', 'R&D', 120, 'amber'], ['fintree:GeneralAdministrativeExpenses', 'G&A', 110, 'amber'], ['fintree:DepreciationAmortization', 'D&A', 20, 'amber']],
    nonop: [['fintree:NonoperatingExpenses', 'Non-Op Expenses', 40, 'red'], ['fintree:NonoperatingIncome', 'Non-Op Income', 15, 'green']],
    tax: [['fintree:CurrentTaxExpense', 'Current Tax', 30, 'red'], ['fintree:DeferredTaxExpense', 'Deferred Tax', 8, 'red']],
  };
  const PLOT_H = 420;
  const ICICLE_H = 620;

  /* ── Data adapter: FINTREE_DATA → design view-model ───────────────── */

  // Statement view, Reg S-X 5-03 order. `roots` are the section HEADER nodes:
  // the chip builder traverses each root's subtree and excludes the roots
  // themselves (so a section's own header/subtotal never appears as its chip),
  // leaving every descendant — including the intermediate GAAP category nodes
  // (Selling/G&A/R&D/D&A, Gross Revenue, Current/Deferred Tax, …). Usually a
  // section has one root = its `src`; `cogs` needs two because `fintree:Cogs`
  // is a SIBLING of the src (a separate child of Gross Profit), not a
  // descendant, so it must be seeded explicitly to be covered. Subtotals are
  // computed separator rows, not sections.
  const SECTION_CFG = [
    { key: 'revenue', kind: 'input', src: 'fintree:NetRevenue', label: 'Revenue', sign: '+', tone: 'green', roots: ['fintree:NetRevenue'] },
    { key: 'cogs', kind: 'input', src: 'fintree:CostOfGoodsSoldCostOfRevenue', label: 'Cost of Revenue', sign: '-', tone: 'red', roots: ['fintree:CostOfGoodsSoldCostOfRevenue', 'fintree:Cogs'] },
    { key: 'grossprofit', kind: 'subtotal', src: 'fintree:GrossProfit', label: 'Gross Profit', tone: 'indigo', formula: 'Revenue − Cost of Revenue' },
    { key: 'opex', kind: 'input', src: 'fintree:OperatingExpenses', label: 'Operating Expenses', sign: '-', tone: 'amber', roots: ['fintree:OperatingExpenses'] },
    { key: 'ebit', kind: 'subtotal', src: 'fintree:OperatingIncome', label: 'Operating Income (EBIT)', tone: 'indigo', formula: 'Gross Profit − Operating Expenses' },
    { key: 'nonop', kind: 'input', src: 'fintree:NonoperatingIncomeExpenses', label: 'Non-Operating Items', sign: '±', tone: 'slate', roots: ['fintree:NonoperatingIncomeExpenses'] },
    { key: 'ebt', kind: 'subtotal', src: 'fintree:PretaxIncome', label: 'Pre-Tax Income (EBT)', tone: 'indigo', formula: 'EBIT ± Non-Operating Items' },
    { key: 'tax', kind: 'input', src: 'fintree:IncomeTaxExpense', label: 'Income Tax', sign: '-', tone: 'red', roots: ['fintree:IncomeTaxExpense'] },
    { key: 'netincome', kind: 'subtotal', src: 'fintree:NetIncome', label: 'Net Income', tone: 'green', formula: 'Pre-Tax Income − Income Tax' },
    { key: 'btl', kind: 'input', src: 'fintree:BelowthelineItems', label: 'Below-the-Line Items', sign: '±', tone: 'slate', roots: ['fintree:BelowthelineItems'] },
  ];

  // First matching ancestor (self included) fixes a node's colour tone.
  const TONE = {
    'fintree:NetIncome': 'indigo', 'fintree:GrossProfit': 'indigo', 'fintree:OperatingIncome': 'indigo', 'fintree:PretaxIncome': 'indigo',
    'fintree:NetRevenue': 'green', 'fintree:GrossRevenue': 'green', 'fintree:RevenueDeductions': 'green', 'fintree:OtherRevenue': 'green', 'fintree:ProductRevenue': 'green', 'fintree:ServiceRevenue': 'green',
    'fintree:CostOfGoodsSoldCostOfRevenue': 'red', 'fintree:Cogs': 'red',
    'fintree:OperatingExpenses': 'amber',
    'fintree:NonoperatingIncomeExpenses': 'slate', 'fintree:NonoperatingIncome': 'green', 'fintree:NonoperatingExpenses': 'red',
    'fintree:IncomeTaxExpense': 'red', 'fintree:CurrentTaxExpense': 'red', 'fintree:DeferredTaxExpense': 'red',
    'fintree:BelowthelineItems': 'slate', 'fintree:DiscontinuedOperations': 'slate', 'fintree:ExtraordinaryItems': 'slate', 'fintree:CumulativeEffectOfAccountingChanges': 'slate',
  };

  function buildPL(DATA) {
    const nodes = DATA.nodes || [];
    const map = {};
    nodes.forEach((n) => { map[n.id] = n; });

    const toneOf = (id) => {
      let cur = id, guard = 0;
      while (cur && guard++ < 64) {
        if (TONE[cur]) return TONE[cur];
        const n = map[cur];
        cur = n ? n.parent_id : null;
      }
      return 'slate';
    };

    const countMemo = {};
    const subCount = (id) => {
      if (countMemo[id] != null) return countMemo[id];
      const n = map[id];
      if (!n) return 0;
      countMemo[id] = 1; // guard against cycles while recursing
      let c = 1;
      (n.children_ids || []).forEach((k) => { if (k !== id) c += subCount(k); });
      return (countMemo[id] = c);
    };

    // Industry overlays: curated emphasize / suppress / rename per overlay.
    const overlays = DATA.industry_overlays || [];
    const emphSets = {}, suppSets = {}, renameByInd = {};
    overlays.forEach((o) => {
      const m = o.modifications || {};
      emphSets[o.industry] = new Set(m.emphasize || []);
      suppSets[o.industry] = new Set(m.suppress || []);
      renameByInd[o.industry] = m.rename || {};
    });
    const industries = [{ v: '', l: 'All Industries (GAAP)' }].concat(
      overlays.map((o) => ({ v: o.industry, l: o.label || String(o.industry || '').replace(/_/g, ' ') }))
    );

    const tree = {};
    const detail = {};
    nodes.forEach((n) => {
      tree[n.id] = { t: toneOf(n.id), l: n.label, n: subCount(n.id), c: (n.children_ids || []).slice(), p: n.parent_id || null };
      const vd = (n.variance_drivers && n.variance_drivers.playbook)
        ? { up: n.variance_drivers.playbook.if_increased, down: n.variance_drivers.playbook.if_decreased, tags: n.variance_drivers.tags || [] }
        : null;
      detail[n.id] = {
        label: n.label, short: n.short_label || '', level: n.level, type: n.node_type,
        nb: n.normal_balance || '', xbrl: n.xbrl_tag || '', def: n.definition || '',
        formula: n.formula_human || '', asc: n.asc_reference || '',
        vd, comp: n.comparability || null, ex: n.example || '',
        coa: n.coa_mapping || null, tags: n.ai_context_tags || [],
        iv: overlays.filter((o) => emphSets[o.industry].has(n.id)).map((o) => o.industry),
        sv: overlays.filter((o) => suppSets[o.industry].has(n.id)).map((o) => o.industry),
      };
    });

    const subtree = (rootId) => {
      const out = [], stack = [rootId], seen = new Set();
      while (stack.length) {
        const id = stack.pop();
        if (seen.has(id)) continue;
        seen.add(id);
        const n = map[id];
        if (!n) continue;
        out.push(n);
        (n.children_ids || []).forEach((c) => stack.push(c));
      }
      return out;
    };

    const sections = SECTION_CFG.map((cfg) => {
      const base = { key: cfg.key, kind: cfg.kind, src: cfg.src, label: cfg.label, tone: cfg.tone, sign: cfg.sign || '', formula: cfg.formula || '', chips: [], count: 0 };
      if (cfg.kind === 'input') {
        const rootSet = new Set(cfg.roots);
        const seen = new Set();
        const chips = [];
        cfg.roots.forEach((rid) => {
          subtree(rid).forEach((n) => {
            if (rootSet.has(n.id) || seen.has(n.id)) return; // exclude section roots + dedup
            seen.add(n.id);
            chips.push({ id: n.id, label: n.label, level: n.level, type: n.node_type, leaf: n.is_leaf });
          });
        });
        base.chips = chips;
        base.count = chips.length;
      }
      return base;
    });

    return { stats: DATA.stats || { total_nodes: nodes.length }, rootId: DATA.root_node_id, tree, detail, sections, industries, renameByInd };
  }

  /* ── Component ────────────────────────────────────────────────────── */
  class Explorer {
    constructor(root, PL, props) {
      this.root = root;
      this.PL = PL;
      this.props = props || {};
      this.state = {
        view: this.props.startView || 'waterfall',
        theme: this.props.startTheme === 'light' ? 'light' : 'dark',
        expanded: {}, full: {},
        selectedId: null, query: '', industry: '',
        drillKey: null, focusId: PL.rootId || null,
        panelOpen: false, searchOpen: false,
      };
      this._handlers = [];
      this._raf = 0;
    }

    /* actions (arrow fields keep `this` bound when used as callbacks) */
    setView = (v) => this.setState({ view: v });
    toggleTheme = () => this.setState((s) => ({ theme: s.theme === 'light' ? 'dark' : 'light' }));
    toggle = (k) => this.setState((s) => ({ expanded: Object.assign({}, s.expanded, { [k]: !s.expanded[k] }) }));
    showFull = (k) => this.setState((s) => ({ full: Object.assign({}, s.full, { [k]: true }) }));
    select = (id) => this.setState({ selectedId: id, panelOpen: true });
    selectBar = (src, key) => this.setState({ selectedId: src, drillKey: BD[key] ? key : null, panelOpen: true });
    setFocus = (id) => this.setState({ focusId: id, selectedId: id, panelOpen: true });
    onSearch = (e) => this.setState({ query: e.target.value, searchOpen: true });
    onIndustry = (e) => {
      const industry = e.target.value;
      // The overlay only affects the Statement view — jump there on select so its
      // effect (emphasis / suppress / rename) is immediately visible.
      this.setState(industry ? { industry, view: 'statement' } : { industry });
    };
    openPanel = () => this.setState({ panelOpen: true });
    closePanel = () => this.setState({ panelOpen: false });
    // Global search: jump to any node from any view.
    selectFromSearch = (id) => this.setState({ selectedId: id, panelOpen: true, query: '', searchOpen: false });
    closeSearch = () => { if (this.state.searchOpen) this.setState({ searchOpen: false }); };

    // Score nodes for the search dropdown (label > id > definition).
    searchNodes(q, limit) {
      q = (q || '').trim().toLowerCase();
      if (q.length < 2) return [];
      const out = [];
      const D = this.PL.detail;
      for (const id in D) {
        const d = D[id];
        const label = (d.label || '').toLowerCase();
        let score = 0;
        if (label === q) score = 100;
        else if (label.startsWith(q)) score = 80;
        else if (label.includes(q)) score = 60;
        else if (id.toLowerCase().includes(q)) score = 40;
        else if ((d.xbrl || '').toLowerCase().includes(q)) score = 30;
        else if ((d.def || '').toLowerCase().includes(q)) score = 15;
        if (score) out.push({ id, label: d.label, type: (d.type || '').replace(/_/g, ' ').toLowerCase(), level: d.level, def: d.def || '', score, lvl: d.level || 99 });
      }
      out.sort((a, b) => b.score - a.score || a.lvl - b.lvl);
      return out.slice(0, limit || 10);
    }

    mount() {
      this.render();
      // One-time document listeners (mount() runs exactly once).
      document.addEventListener('keydown', (e) => {
        if (e.key !== 'Escape') return;
        if (this.state.searchOpen) this.closeSearch();
        else if (this.state.panelOpen) this.closePanel();
      });
      // Close the search dropdown on any pointer-down outside the search box.
      // Capture phase, so it still fires even though child click handlers
      // stopPropagation during the bubble phase.
      document.addEventListener('mousedown', (e) => {
        if (this.state.searchOpen && !(e.target.closest && e.target.closest('#ftSearchBox'))) this.closeSearch();
      }, true);
    }

    isMobile() {
      return typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(max-width: 900px)').matches;
    }

    setState(patch) {
      const next = typeof patch === 'function' ? patch(this.state) : patch;
      this.state = Object.assign({}, this.state, next);
      if (this._raf) return;
      this._raf = requestAnimationFrame(() => { this._raf = 0; this.render(); });
    }

    reduced() {
      return typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    }

    applyTheme() {
      const t = this.state.theme === 'light' ? LIGHT : DARK;
      for (const k in t) this.root.style.setProperty(k, t[k]);
    }

    reg(fn) { const i = this._handlers.length; this._handlers.push(fn); return i; }

    attach() {
      const H = this._handlers, r = this.root;
      r.querySelectorAll('[data-click]').forEach((el) => {
        const f = H[+el.getAttribute('data-click')];
        if (f) el.addEventListener('click', (e) => { e.stopPropagation(); f(e); });
      });
      r.querySelectorAll('[data-input]').forEach((el) => {
        const f = H[+el.getAttribute('data-input')];
        if (f) el.addEventListener('input', f);
      });
      r.querySelectorAll('[data-change]').forEach((el) => {
        const f = H[+el.getAttribute('data-change')];
        if (f) el.addEventListener('change', f);
      });
    }

    /* ── builders (ported from the .dc component) ───────────────────── */
    buildWaterfall() {
      const colW = 100 / SPINE.length, scale = (PLOT_H - 18) / 1000;
      const bars = SPINE.map((s, i) => {
        const tk = tints(s.tone);
        const topPx = PLOT_H - s.hi * scale, hPx = (s.hi - s.lo) * scale;
        const left = i * colW + colW * 0.2, width = colW * 0.6;
        const isNet = s.key === 'netincome';
        const grad = `linear-gradient(180deg, color-mix(in srgb, ${tk.color} 82%, transparent), ${tk.color})`;
        const sel = this.state.selectedId === s.src;
        const style = { position: 'absolute', left: left + '%', width: width + '%', top: topPx + 'px', height: hPx + 'px', background: grad, borderRadius: s.type === 'delta' ? '5px' : '6px 6px 4px 4px', cursor: 'pointer', transformOrigin: s.type === 'delta' ? 'center top' : 'center bottom', boxShadow: sel ? ('0 0 0 2px var(--bg2), 0 0 0 4px ' + tk.color) : (isNet ? ('0 6px 18px ' + tk.soft) : 'none'), border: '1px solid color-mix(in srgb, ' + tk.color + ' 70%, transparent)' };
        const labelStyle = { position: 'absolute', left: left + '%', width: width + '%', top: (topPx - 23) + 'px', display: 'flex', justifyContent: 'center' };
        const nameStyle = { position: 'absolute', left: (i * colW) + '%', width: colW + '%', top: (PLOT_H + 12) + 'px', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '2px' };
        const pfx = s.val < 0 ? '−$' : '$';
        return { i: i, key: s.key, name: s.label, origin: s.type === 'delta' ? 'top' : 'bottom', cnt: Math.abs(s.val), pfx: pfx, disp: pfx + fmt(Math.abs(s.val)) + 'M', valColor: tk.color, marginLabel: s.margin || '', style: style, labelStyle: labelStyle, nameStyle: nameStyle, onClick: () => this.selectBar(s.src, s.key) };
      });
      const connectors = SPINE.slice(0, -1).map((s, i) => {
        const bv = s.type === 'delta' ? s.lo : s.hi;
        const y = PLOT_H - bv * scale;
        return { style: { position: 'absolute', left: (i * colW + colW * 0.5) + '%', width: colW + '%', top: y + 'px', height: 0, borderTop: '1.5px dashed var(--ink4)', transformOrigin: 'left center' } };
      });
      let drill = null; const dk = this.state.drillKey;
      if (dk && BD[dk]) {
        const items = BD[dk]; const sum = items.reduce((a, x) => a + x[2], 0);
        const segments = items.map((x) => {
          const tk = tints(x[3] || 'slate');
          return { label: x[1], valLabel: '$' + fmt(x[2]) + 'M', color: tk.color, onClick: () => this.select(x[0]), barStyle: { flex: x[2] / sum, height: '100%', background: tk.color, border: 'none', cursor: 'pointer', transformOrigin: 'left center', minWidth: '2px' } };
        });
        const sec = SPINE.find((s) => s.key === dk);
        drill = { title: sec.label + ' breakdown', total: '$' + fmt(sum) + 'M', segments: segments };
      }
      return { bars: bars, connectors: connectors, hasDrill: !!drill, drill: drill || { segments: [] } };
    }

    buildIcicle() {
      const T = this.PL.tree, maxDepth = 3, cw = 100 / (maxDepth + 1), focus = this.state.focusId || this.PL.rootId;
      const ICH = ICICLE_H, cells = [];
      const lay = (id, d, y, h) => {
        const t = T[id]; if (!t) return; const tk = tints(t.t);
        const sel = this.state.selectedId === id;
        const isFocus = d === 0;
        const px = h / 100 * ICH;
        const bg = isFocus ? `color-mix(in srgb, ${tk.color} 30%, var(--panel))` : `color-mix(in srgb, ${tk.color} ${16 + (maxDepth - d) * 3}%, var(--panel2))`;
        const showLabel = px >= 22, showCount = px >= 44, tiny = px < 8;
        cells.push({
          id: id, label: t.l, title: t.l + ' · ' + t.n + (t.n === 1 ? ' node' : ' nodes'), countLabel: t.n + (t.n === 1 ? ' node' : ' nodes'), showCount: showCount,
          showLabel: showLabel, textColor: 'var(--ink)', subColor: 'var(--ink3)',
          style: {
            position: 'absolute', top: y + '%', height: h + '%', width: (cw - 0.5) + '%',
            left: (d * cw) + '%', background: bg, border: tiny ? 'none' : '1px solid var(--bg2)', borderLeft: (tiny ? '2px' : '3px') + ' solid ' + tk.color, borderRadius: tiny ? '2px' : (px < 22 ? '4px' : '6px'),
            padding: showLabel ? '4px 10px' : '0 10px', textAlign: 'left', cursor: 'pointer', overflow: 'hidden', display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: '2px',
            boxShadow: sel ? ('inset 0 0 0 2px ' + tk.color) : 'none', transition: 'background .15s',
          },
          onClick: () => (T[id].c.length ? this.setFocus(id) : this.select(id)),
        });
        if (d >= maxDepth) return;
        const kids = t.c; if (!kids.length) return;
        const wt = (k) => Math.sqrt((T[k] ? T[k].n : 0) + 1);
        const tot = kids.reduce((s, k) => s + wt(k), 0); let yy = y;
        kids.forEach((k) => { if (!T[k]) return; const kh = h * (wt(k) / tot); lay(k, d + 1, yy, kh); yy += kh; });
      };
      lay(focus, 0, 0, 100);
      const bc = []; let c = focus, guard = 0;
      while (c && guard++ < 64) { bc.unshift(c); c = T[c] ? T[c].p : null; }
      const breadcrumb = bc.filter((id) => T[id]).map((id, i) => ({ label: T[id].l, sep: i > 0, color: id === focus ? 'var(--ink)' : 'var(--ink3)', onClick: () => this.setFocus(id) }));
      return { cells: cells, breadcrumb: breadcrumb };
    }

    buildSel() {
      const id = this.state.selectedId;
      if (!id || !this.PL || !this.PL.detail[id]) return { hasSel: false, noSel: true, sel: null };
      const d = this.PL.detail[id];
      const accent = d.nb === 'CREDIT' ? 'green' : (d.nb === 'DEBIT' ? 'red' : 'indigo'); const ak = tints(accent);
      const nbStyle = { fontFamily: "'IBM Plex Mono',monospace", fontSize: '10px', letterSpacing: '.06em', textTransform: 'uppercase', color: ak.color, background: ak.tint, border: '1px solid ' + ak.border, borderRadius: '6px', padding: '3px 8px' };
      const coaRows = d.coa ? [['QuickBooks', d.coa.quickbooks], ['NetSuite', d.coa.netsuite], ['SAP', d.coa.sap]].filter((r) => r[1]).map((r) => ({ sys: r[0], val: r[1] })) : [];
      const tags = (d.tags || []).map((t) => t.replace(/_/g, ' '));
      const vdTags = (d.vd && d.vd.tags) ? d.vd.tags.map((t) => t.replace(/_/g, ' ')) : [];
      const compEx = (d.comp && d.comp.examples) ? d.comp.examples : [];
      const sel = {
        label: d.label, short: (d.short && d.short !== d.label) ? d.short : '', levelLabel: 'L' + d.level, typeLabel: (d.type || '').replace(/_/g, ' ').toLowerCase(), nb: d.nb || '—', nbStyle: nbStyle,
        xbrl: d.xbrl || '—', def: d.def || 'No definition available.', formula: d.formula || '', hasFormula: !!(d.formula && d.formula.trim()), asc: d.asc || '—',
        accentColor: ak.color, accentTint: ak.tint, accentBorder: ak.border,
        hasVd: !!d.vd, vdUp: d.vd ? d.vd.up : '', vdDown: d.vd ? d.vd.down : '', vdTags: vdTags, hasVdTags: vdTags.length > 0,
        hasComp: !!(d.comp && (d.comp.variations || compEx.length)), compVar: d.comp ? d.comp.variations : '', compEx: compEx,
        hasExample: !!(d.ex && d.ex.trim()), example: d.ex || '', coaRows: coaRows, hasCoa: coaRows.length > 0, tags: tags, hasAiTags: tags.length > 0,
      };
      return { hasSel: true, noSel: false, sel: sel };
    }

    buildStatement() {
      const query = this.state.query, industry = this.state.industry; const q = (query || '').trim().toLowerCase();
      return this.PL.sections.map((s) => {
        const tk = tints(s.tone); const isInput = s.kind === 'input', isSubtotal = s.kind === 'subtotal', isNet = s.key === 'netincome';
        const allChips = s.chips || [];
        // Overlay counts for this section, over what is actually rendered — chips
        // (the section root/header is not a chip). Shown in the header even collapsed.
        const emphN = industry ? allChips.filter((c) => { const d = this.PL.detail[c.id]; return d && d.iv && d.iv.includes(industry); }).length : 0;
        const suppN = industry ? allChips.filter((c) => { const d = this.PL.detail[c.id]; return d && d.sv && d.sv.includes(industry); }).length : 0;
        // Renames apply to both chips and the (visible) section header.
        const renN = industry ? (() => { const rm = (this.PL.renameByInd && this.PL.renameByInd[industry]) || {}; let n = allChips.filter((c) => rm[c.id]).length; if (rm[s.src]) n += 1; return n; })() : 0;
        const labelMatch = !q || s.label.toLowerCase().includes(q);
        const chipMatch = (c) => { const d = this.PL.detail[c.id]; return c.label.toLowerCase().includes(q) || (d && (d.xbrl || '').toLowerCase().includes(q)); };
        const hasMatch = labelMatch || allChips.some(chipMatch);
        const matchedChips = (q && !labelMatch) ? allChips.filter(chipMatch) : allChips;
        const open = isInput && (this.state.expanded[s.key] || (!!q && hasMatch && matchedChips.length > 0));
        const dim = isInput && !!q && !hasMatch;
        const full = this.state.full[s.key];
        const renames = (industry && this.PL.renameByInd && this.PL.renameByInd[industry]) || {};
        let pool = open ? matchedChips.slice() : [];
        // With an industry active, float emphasized chips up and sink suppressed ones.
        if (open && industry) {
          const rank = (c) => { const d = this.PL.detail[c.id]; if (d && d.sv && d.sv.includes(industry)) return 2; if (d && d.iv && d.iv.includes(industry)) return 0; return 1; };
          pool.sort((a, b) => rank(a) - rank(b));
        }
        let hasMore = false, moreLabel = '';
        if (open && !full && pool.length > 24) { hasMore = true; moreLabel = '+' + (pool.length - 24) + ' more'; pool = pool.slice(0, 24); }
        const chips = pool.map((c) => {
          const d = this.PL.detail[c.id]; const isCat = c.type !== 'LINE_ITEM';
          const emph = !!industry && d && d.iv && d.iv.includes(industry);
          const supp = !!industry && d && d.sv && d.sv.includes(industry);
          const isSelChip = this.state.selectedId === c.id;
          let bg = 'var(--panel)', bd = '1px solid var(--line)', col = 'var(--ink2)', fw = '400';
          if (isCat) { bg = tk.tint; bd = '1px solid ' + tk.border; col = tk.color; fw = '600'; }
          if (emph) { bd = '1px solid ' + tk.color; col = 'var(--ink)'; bg = `color-mix(in srgb, var(--c-${s.tone}) 16%, var(--panel))`; }
          if (isSelChip) { bd = '1px solid var(--ink2)'; col = 'var(--ink)'; bg = 'var(--panel2)'; }
          const style = { display: 'inline-flex', alignItems: 'center', gap: '6px', fontFamily: "'IBM Plex Mono',monospace", fontSize: '11px', fontWeight: fw, letterSpacing: '.02em', padding: '6px 10px', borderRadius: '7px', background: bg, border: bd, color: col, opacity: (!!industry && !emph && !isSelChip) ? 0.4 : 1, textTransform: 'uppercase', whiteSpace: 'nowrap', transition: 'background .15s,border-color .15s,opacity .2s' };
          if (supp) { style.textDecoration = 'line-through'; style.opacity = 0.4; style.borderStyle = 'dashed'; }
          return { id: c.id, label: renames[c.id] || c.label, isCat: isCat, marker: supp ? '×' : (isCat ? '▸' : '·'), markerColor: supp ? 'var(--c-red)' : (isCat ? col : 'var(--ink4)'), onClick: () => this.select(c.id), style: style };
        });
        const selSec = this.state.selectedId === s.src;
        const cardStyle = { background: tk.tint, border: '1px solid ' + tk.border, borderLeft: '3px solid ' + tk.color, borderRadius: '13px', overflow: 'hidden', boxShadow: selSec ? ('0 0 0 2px ' + tk.color + ', var(--shadow)') : 'none', transition: 'box-shadow .15s' };
        const iconStyle = { width: '35px', height: '35px', borderRadius: '9px', background: tk.soft, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: "'IBM Plex Mono',monospace", fontWeight: 600, fontSize: '14px', color: tk.color, flexShrink: 0 };
        const rowStyle = { display: 'flex', alignItems: 'center', gap: '13px', width: '100%', textAlign: 'left', padding: '13px 15px', borderRadius: '13px', background: isNet ? tk.tint : 'transparent', border: isNet ? ('1px solid ' + tk.border) : ('1px dashed ' + tk.border), boxShadow: selSec ? ('0 0 0 2px ' + tk.color) : 'none', transition: 'box-shadow .15s' };
        const subIconStyle = Object.assign({}, iconStyle, { fontWeight: 700, fontSize: '15px' });
        return { key: s.key, label: renames[s.src] || s.label, isInput: isInput, isSubtotal: isSubtotal, signLabel: SIGN[s.sign] || '', count: s.count, emphN: emphN, suppN: suppN, renN: renN, icon: ICON[s.key] || '·', caret: open ? '▾' : '▸', open: open, opacity: dim ? 0.4 : 1, cardStyle: cardStyle, iconStyle: iconStyle, rowStyle: rowStyle, subIconStyle: subIconStyle, labelColor: tk.color, formula: s.formula || '', chips: chips, hasMore: hasMore, moreLabel: moreLabel, onSelect: () => this.select(s.src), onToggle: () => this.toggle(s.key), onMore: () => this.showFull(s.key) };
      });
    }

    renderVals() {
      const s = this.state;
      const view = s.view, theme = s.theme, query = s.query, industry = s.industry;
      const tw = (k) => ({ w: view === k ? '700' : '500', c: view === k ? 'var(--ink)' : 'var(--ink3)', bg: view === k ? 'var(--panel2)' : 'transparent', bd: view === k ? 'var(--line2)' : 'transparent' });
      const tWf = tw('waterfall'), tHi = tw('hierarchy'), tSt = tw('statement');
      const industries = (this.PL.industries && this.PL.industries.length) ? this.PL.industries : [{ v: '', l: 'All Industries (GAAP)' }];

      let wf = { bars: [], connectors: [], hasDrill: false, drill: { segments: [] } }, ic = { cells: [], breadcrumb: [] }, sections = [];
      // Suppressed nodes are still rendered (struck through), so they stay counted
      // as visible; only the search query hides nodes. The overlay banner reports
      // the suppressed count separately.
      let total = (this.PL.stats && this.PL.stats.total_nodes) || 234, visible = total;
      if (query.trim()) {
        const qq = query.trim().toLowerCase();
        visible = Object.keys(this.PL.detail).filter((id) => { const d = this.PL.detail[id]; return d.label.toLowerCase().includes(qq) || (d.xbrl || '').toLowerCase().includes(qq); }).length;
      }
      const searchResults = this.searchNodes(query, 10);
      const showSearch = this.state.searchOpen && query.trim().length >= 2;
      if (view === 'waterfall') wf = this.buildWaterfall();
      else if (view === 'hierarchy') ic = this.buildIcicle();
      else sections = this.buildStatement();
      // Overlay summary sums the per-section rendered counts, so it can never
      // contradict the section badges (only shown in the Statement view).
      let overlay = null;
      if (industry && view === 'statement') {
        const ind = (this.PL.industries || []).find((o) => o.v === industry);
        let e = 0, sp = 0, r = 0;
        sections.forEach((sec) => { e += sec.emphN || 0; sp += sec.suppN || 0; r += sec.renN || 0; });
        overlay = { label: ind ? ind.l : industry, emph: e, supp: sp, rename: r };
      }

      return Object.assign({
        themeDot: theme === 'light' ? 'var(--c-amber)' : 'var(--c-indigo)',
        themeTitle: theme === 'light' ? 'Switch to dark theme' : 'Switch to light theme',
        query: query, industry: industry, industries: industries,
        wfW: tWf.w, wfC: tWf.c, wfBg: tWf.bg, wfBd: tWf.bd,
        hiW: tHi.w, hiC: tHi.c, hiBg: tHi.bg, hiBd: tHi.bd,
        stW: tSt.w, stC: tSt.c, stBg: tSt.bg, stBd: tSt.bd,
        isWaterfall: view === 'waterfall', isHierarchy: view === 'hierarchy', isStatement: view === 'statement',
        showFooter: this.props.showFooter !== false, plotH: PLOT_H, panelOpen: s.panelOpen,
        searchResults: searchResults, showSearch: showSearch, overlay: overlay,
        wf: wf, ic: ic, sections: sections, total: total, visible: visible,
      }, this.buildSel());
    }

    /* ── templates ──────────────────────────────────────────────────── */
    detailHtml(sel) {
      return `
      <div style="display:flex;flex-direction:column;gap:19px">
        <div data-anim="detail-item" style="display:flex;flex-wrap:wrap;gap:7px">
          <span style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink3);border:1px solid var(--line2);border-radius:6px;padding:3px 8px">${esc(sel.levelLabel)}</span>
          <span style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink3);border:1px solid var(--line2);border-radius:6px;padding:3px 8px">${esc(sel.typeLabel)}</span>
          <span style="${st(sel.nbStyle)}">${esc(sel.nb)}</span>
        </div>
        <div data-anim="detail-item">
          <h2 style="margin:0;font-size:23px;font-weight:800;line-height:1.18;letter-spacing:-.01em;color:var(--ink)">${esc(sel.label)}</h2>
          ${sel.short ? `<div style="margin-top:4px;font-size:13px;color:var(--ink3)">${esc(sel.short)}</div>` : ''}
        </div>
        <div data-anim="detail-item" style="display:flex;flex-direction:column;gap:7px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)">XBRL Tag</div>
          <code style="font-family:'IBM Plex Mono',monospace;font-size:12px;color:${sel.accentColor};background:${sel.accentTint};border:1px solid ${sel.accentBorder};border-radius:9px;padding:10px 12px;word-break:break-all;line-height:1.4">${esc(sel.xbrl)}</code>
        </div>
        <div data-anim="detail-item" style="display:flex;flex-direction:column;gap:7px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)">Definition</div>
          <p style="margin:0;font-size:14px;line-height:1.6;color:var(--ink2)">${esc(sel.def)}</p>
        </div>
        ${sel.hasFormula ? `
        <div data-anim="detail-item" style="display:flex;flex-direction:column;gap:7px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)">Formula</div>
          <code style="font-family:'IBM Plex Mono',monospace;font-size:12.5px;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:10px 12px;line-height:1.5">${esc(sel.formula)}</code>
        </div>` : ''}
        <div data-anim="detail-item" style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
          <div style="background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:11px 12px;display:flex;flex-direction:column;gap:5px">
            <div style="font-family:'IBM Plex Mono',monospace;font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--ink3)">ASC Reference</div>
            <div style="font-family:'IBM Plex Mono',monospace;font-size:13px;color:var(--ink)">${esc(sel.asc)}</div>
          </div>
          <div style="background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:11px 12px;display:flex;flex-direction:column;gap:5px">
            <div style="font-family:'IBM Plex Mono',monospace;font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--ink3)">Normal Balance</div>
            <div style="font-family:'IBM Plex Mono',monospace;font-size:13px;color:var(--ink)">${esc(sel.nb)}</div>
          </div>
        </div>
        ${sel.hasVd ? `
        <div data-anim="detail-item" style="display:flex;flex-direction:column;gap:9px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)">Variance Drivers</div>
          <div style="border:1px solid color-mix(in srgb,var(--c-green) 26%,var(--line));background:color-mix(in srgb,var(--c-green) 8%,var(--panel));border-radius:11px;padding:12px 13px">
            <div style="display:flex;align-items:center;gap:7px;margin-bottom:6px"><span style="color:var(--c-green);font-size:11px">▲</span><span style="font-size:12px;font-weight:700;color:var(--c-green)">If increased</span></div>
            <p style="margin:0;font-size:12.5px;line-height:1.55;color:var(--ink2)">${esc(sel.vdUp)}</p>
          </div>
          <div style="border:1px solid color-mix(in srgb,var(--c-red) 26%,var(--line));background:color-mix(in srgb,var(--c-red) 8%,var(--panel));border-radius:11px;padding:12px 13px">
            <div style="display:flex;align-items:center;gap:7px;margin-bottom:6px"><span style="color:var(--c-red);font-size:11px">▼</span><span style="font-size:12px;font-weight:700;color:var(--c-red)">If decreased</span></div>
            <p style="margin:0;font-size:12.5px;line-height:1.55;color:var(--ink2)">${esc(sel.vdDown)}</p>
          </div>
          ${sel.hasVdTags ? `<div style="display:flex;flex-wrap:wrap;gap:6px">${sel.vdTags.map((t) => `<span style="font-family:'IBM Plex Mono',monospace;font-size:10px;text-transform:uppercase;letter-spacing:.03em;padding:4px 8px;border-radius:6px;background:var(--panel2);border:1px solid var(--line);color:var(--ink3)">${esc(t)}</span>`).join('')}</div>` : ''}
        </div>` : ''}
        ${sel.hasComp ? `
        <div data-anim="detail-item" style="display:flex;flex-direction:column;gap:9px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)">Comparability</div>
          ${sel.compVar ? `<p style="margin:0;font-size:12.5px;line-height:1.55;color:var(--ink3)">${esc(sel.compVar)}</p>` : ''}
          <div style="display:flex;flex-direction:column;gap:6px">
            ${sel.compEx.map((e) => `
              <div style="display:flex;gap:11px;align-items:baseline;padding:9px 12px;background:var(--panel);border:1px solid var(--line);border-radius:10px">
                <span style="font-weight:700;font-size:12.5px;color:var(--ink);min-width:92px;flex-shrink:0">${esc(e.company)}</span>
                <span style="font-size:12px;color:var(--ink3);line-height:1.45">${esc(e.treatment)}</span>
              </div>`).join('')}
          </div>
        </div>` : ''}
        ${sel.hasExample ? `
        <div data-anim="detail-item" style="display:flex;flex-direction:column;gap:7px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)">Real-World Example</div>
          <p style="margin:0;font-size:12.5px;line-height:1.6;color:var(--ink2);border-left:2px solid var(--c-amber);padding-left:12px">${esc(sel.example)}</p>
        </div>` : ''}
        ${sel.hasCoa ? `
        <div data-anim="detail-item" style="display:flex;flex-direction:column;gap:7px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)">Chart of Accounts</div>
          <div style="display:flex;flex-direction:column;border:1px solid var(--line);border-radius:10px;overflow:hidden">
            ${sel.coaRows.map((r) => `<div style="display:flex;justify-content:space-between;gap:12px;padding:9px 12px;border-bottom:1px solid var(--line);font-family:'IBM Plex Mono',monospace;font-size:11.5px"><span style="color:var(--ink3)">${esc(r.sys)}</span><span style="color:var(--ink);text-align:right">${esc(r.val)}</span></div>`).join('')}
          </div>
        </div>` : ''}
        ${sel.hasAiTags ? `
        <div data-anim="detail-item" style="display:flex;flex-direction:column;gap:7px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3)">AI Context Tags</div>
          <div style="display:flex;flex-wrap:wrap;gap:6px">${sel.tags.map((t) => `<span style="font-family:'IBM Plex Mono',monospace;font-size:10px;text-transform:uppercase;letter-spacing:.04em;padding:4px 8px;border-radius:6px;background:var(--panel2);border:1px solid var(--line);color:var(--ink3)">${esc(t)}</span>`).join('')}</div>
        </div>` : ''}
      </div>`;
    }

    template(v) {
      return `
      <header class="ft-header">
        <div style="display:flex;align-items:center;gap:11px">
          <div style="width:28px;height:28px;border-radius:8px;background:linear-gradient(150deg,var(--c-green),color-mix(in srgb,var(--c-green) 55%,#0c5a3a));display:flex;align-items:center;justify-content:center;box-shadow:0 2px 10px color-mix(in srgb,var(--c-green) 40%,transparent)">
            <span style="font-family:'IBM Plex Mono',monospace;font-weight:600;font-size:15px;color:#06140d">F</span>
          </div>
          <div style="display:flex;flex-direction:column;line-height:1.05">
            <span style="font-weight:800;font-size:17px;letter-spacing:-.01em;color:var(--ink)">FinTree</span>
            <span style="font-family:'IBM Plex Mono',monospace;font-size:9.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--ink3)">GAAP P&amp;L Explorer</span>
          </div>
        </div>
        <div class="ft-spacer" style="flex:1"></div>
        <div role="group" aria-label="View" style="display:flex;align-items:center;gap:3px;padding:4px;background:var(--panel);border:1px solid var(--line);border-radius:11px">
          <button aria-pressed="${v.isWaterfall}" data-click="${this.reg(() => this.setView('waterfall'))}" style="padding:7px 15px;border-radius:8px;font-size:13px;font-weight:${v.wfW};color:${v.wfC};background:${v.wfBg};border:1px solid ${v.wfBd}">Waterfall</button>
          <button aria-pressed="${v.isHierarchy}" data-click="${this.reg(() => this.setView('hierarchy'))}" style="padding:7px 15px;border-radius:8px;font-size:13px;font-weight:${v.hiW};color:${v.hiC};background:${v.hiBg};border:1px solid ${v.hiBd}">Hierarchy</button>
          <button aria-pressed="${v.isStatement}" data-click="${this.reg(() => this.setView('statement'))}" style="padding:7px 15px;border-radius:8px;font-size:13px;font-weight:${v.stW};color:${v.stC};background:${v.stBg};border:1px solid ${v.stBd}">Statement</button>
        </div>
        <div class="ft-spacer" style="flex:1"></div>
        <div id="ftSearchBox" style="position:relative">
          <label style="display:flex;align-items:center;gap:9px;width:230px;height:37px;padding:0 13px;background:var(--panel);border:1px solid var(--line);border-radius:10px">
            <span aria-hidden="true" style="font-size:15px;color:var(--ink3)">⌕</span>
            <input id="ftSearch" value="${esc(v.query)}" data-input="${this.reg(this.onSearch)}" placeholder="Search nodes…" aria-label="Search nodes" role="combobox" aria-expanded="${v.showSearch}" aria-controls="ftSearchList" autocomplete="off" style="flex:1;min-width:0;background:none;border:none;outline:none;color:var(--ink);font-size:13px"/>
          </label>
          ${v.showSearch ? `<div id="ftSearchList" role="listbox" aria-label="Search results" style="position:absolute;top:calc(100% + 6px);left:0;width:320px;max-height:340px;overflow:auto;background:var(--panel);border:1px solid var(--line2);border-radius:11px;box-shadow:var(--shadow);z-index:60;padding:5px">
            ${v.searchResults.length ? v.searchResults.map((r) => `<button role="option" data-click="${this.reg(() => this.selectFromSearch(r.id))}" style="display:flex;flex-direction:column;gap:2px;width:100%;text-align:left;padding:8px 10px;border-radius:8px;background:transparent">
              <span style="font-size:13px;font-weight:600;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:290px">${esc(r.label)}</span>
              <span style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.03em;color:var(--ink3)">${esc(r.type)} · L${r.level}</span>
            </button>`).join('') : `<div style="padding:10px 11px;font-size:12px;color:var(--ink3)">No matches</div>`}
          </div>` : ''}
        </div>
        <div style="position:relative;display:flex;align-items:center">
          <select data-change="${this.reg(this.onIndustry)}" aria-label="Industry overlay" style="height:37px;padding:0 30px 0 13px;background:var(--panel);border:1px solid var(--line);border-radius:10px;color:var(--ink2);font-size:13px">
            ${v.industries.map((opt) => `<option value="${esc(opt.v)}"${opt.v === v.industry ? ' selected' : ''}>${esc(opt.l)}</option>`).join('')}
          </select>
          <span aria-hidden="true" style="position:absolute;right:11px;pointer-events:none;color:var(--ink3);font-size:11px">▾</span>
        </div>
        <button data-click="${this.reg(this.toggleTheme)}" title="${esc(v.themeTitle)}" aria-label="${esc(v.themeTitle)}" style="height:37px;width:37px;display:flex;align-items:center;justify-content:center;background:var(--panel);border:1px solid var(--line);border-radius:10px;color:var(--ink2)">
          <span aria-hidden="true" style="width:11px;height:11px;border-radius:50%;background:${v.themeDot};box-shadow:0 0 8px ${v.themeDot}"></span>
        </button>
      </header>

      <main class="ft-main">
        <section class="ft-content">
          ${v.isWaterfall ? this.waterfallHtml(v) : ''}
          ${v.isHierarchy ? this.hierarchyHtml(v) : ''}
          ${v.isStatement ? this.statementHtml(v) : ''}
        </section>

        <aside id="ftDetail" class="ft-aside${v.panelOpen ? ' open' : ''}" aria-label="Node detail">
          <button class="ft-aside-close" data-click="${this.reg(this.closePanel)}" aria-label="Close detail">✕</button>
          ${v.noSel ? `
            <div style="display:flex;flex-direction:column;gap:15px;height:100%;justify-content:center;align-items:flex-start;padding-bottom:40px">
              <div style="font-family:'IBM Plex Mono',monospace;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink3)">Node Detail</div>
              <div aria-hidden="true" style="width:48px;height:48px;border-radius:13px;border:1px solid var(--line2);display:flex;align-items:center;justify-content:center;color:var(--ink4);font-size:22px">◎</div>
              <h2 style="margin:0;font-size:19px;font-weight:700;color:var(--ink)">Select a node</h2>
              <p style="margin:0;font-size:13px;line-height:1.6;color:var(--ink3);max-width:290px">Click any bar, band, or row to view its full details — definition, formula, XBRL tags, variance drivers, comparability, and chart-of-accounts mappings.</p>
            </div>` : ''}
          ${v.hasSel ? this.detailHtml(v.sel) : ''}
        </aside>
      </main>

      ${v.showFooter ? `
      <footer class="ft-footer">
        <span>NODES <b style="color:var(--ink2);font-weight:600">${v.total}</b></span>
        <span style="color:var(--ink4)">·</span>
        <span>VISIBLE <b style="color:var(--ink2);font-weight:600">${v.visible}</b></span>
        <span style="color:var(--ink4)">·</span>
        <span>US GAAP · REG S-X 5-03</span>
        <span style="flex:1"></span>
        <span style="display:flex;align-items:center;gap:6px"><span aria-hidden="true" style="width:7px;height:7px;border-radius:50%;background:var(--c-green)"></span>Revenue</span>
        <span style="display:flex;align-items:center;gap:6px"><span aria-hidden="true" style="width:7px;height:7px;border-radius:50%;background:var(--c-red)"></span>Cost</span>
        <span style="display:flex;align-items:center;gap:6px"><span aria-hidden="true" style="width:7px;height:7px;border-radius:50%;background:var(--c-amber)"></span>OpEx</span>
        <span style="display:flex;align-items:center;gap:6px"><span aria-hidden="true" style="width:7px;height:7px;border-radius:50%;background:var(--c-indigo)"></span>Subtotal</span>
      </footer>` : ''}

      <button class="ft-detail-toggle" data-click="${this.reg(this.openPanel)}" aria-label="Show node detail" aria-expanded="${v.panelOpen}" aria-controls="ftDetail">◉ Detail</button>`;
    }

    waterfallHtml(v) {
      return `
      <div>
        <div style="display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:6px;flex-wrap:wrap">
          <div>
            <div style="font-family:'IBM Plex Mono',monospace;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink3)">P&amp;L Bridge · Waterfall</div>
            <h1 style="margin:6px 0 0;font-size:22px;font-weight:800;letter-spacing:-.01em;color:var(--ink)">How revenue becomes net income</h1>
          </div>
          <div style="display:flex;gap:22px">
            <div style="display:flex;flex-direction:column;align-items:flex-end">
              <span style="font-family:'IBM Plex Mono',monospace;font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--ink3)">Net Income</span>
              <span data-count="127" data-prefix="$" data-suffix="M" style="font-family:'IBM Plex Mono',monospace;font-size:26px;font-weight:600;color:var(--c-green);line-height:1.1">$127M</span>
            </div>
            <div style="display:flex;flex-direction:column;align-items:flex-end">
              <span style="font-family:'IBM Plex Mono',monospace;font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--ink3)">Net Margin</span>
              <span style="font-family:'IBM Plex Mono',monospace;font-size:26px;font-weight:600;color:var(--ink);line-height:1.1">12.7%</span>
            </div>
          </div>
        </div>
        <div style="background:var(--panel);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);padding:38px 18px 62px;overflow:visible">
          <div style="position:relative;width:100%;height:${v.plotH}px">
            <div style="position:absolute;left:0;right:0;top:${v.plotH}px;height:1px;background:var(--line2)"></div>
            ${v.wf.connectors.map((cn) => `<div data-anim="wconn" style="${st(cn.style)}"></div>`).join('')}
            ${v.wf.bars.map((b) => `
              <div>
                <button data-click="${this.reg(b.onClick)}" data-anim="wbar" data-i="${b.i}" data-origin="${b.origin}" aria-label="${esc(b.name + ' ' + b.disp)}" style="${st(b.style)}"></button>
                <div data-anim="wlabel" style="${st(b.labelStyle)}">
                  <span data-count="${b.cnt}" data-prefix="${esc(b.pfx)}" data-suffix="M" style="font-family:'IBM Plex Mono',monospace;font-size:12.5px;font-weight:600;color:${b.valColor}">${esc(b.disp)}</span>
                </div>
                <div style="${st(b.nameStyle)}">
                  <span style="font-size:11.5px;font-weight:600;color:var(--ink2);text-align:center;line-height:1.15">${esc(b.name)}</span>
                  ${b.marginLabel ? `<span style="font-family:'IBM Plex Mono',monospace;font-size:10px;color:var(--ink3)">${esc(b.marginLabel)}</span>` : ''}
                </div>
              </div>`).join('')}
          </div>
        </div>
        ${v.wf.hasDrill ? `
        <div style="margin-top:16px;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px 18px">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:13px">
            <div style="font-weight:700;font-size:14px;color:var(--ink)">${esc(v.wf.drill.title)}</div>
            <div style="font-family:'IBM Plex Mono',monospace;font-size:11px;color:var(--ink3)">${esc(v.wf.drill.total)}</div>
          </div>
          <div style="display:flex;width:100%;height:34px;border-radius:8px;overflow:hidden;gap:2px">
            ${v.wf.drill.segments.map((seg) => `<button data-click="${this.reg(seg.onClick)}" data-anim="dseg" aria-label="${esc(seg.label + ' ' + seg.valLabel)}" style="${st(seg.barStyle)}"></button>`).join('')}
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:7px 16px;margin-top:13px">
            ${v.wf.drill.segments.map((seg) => `
              <button data-click="${this.reg(seg.onClick)}" style="display:flex;align-items:center;gap:8px;background:none">
                <span aria-hidden="true" style="width:10px;height:10px;border-radius:3px;background:${seg.color}"></span>
                <span style="font-size:12.5px;color:var(--ink2)">${esc(seg.label)}</span>
                <span style="font-family:'IBM Plex Mono',monospace;font-size:12px;color:var(--ink);font-weight:600">${esc(seg.valLabel)}</span>
              </button>`).join('')}
          </div>
        </div>` : ''}
        <div style="margin-top:14px;display:flex;align-items:center;gap:8px;font-family:'IBM Plex Mono',monospace;font-size:10.5px;color:var(--ink3)">
          <span aria-hidden="true" style="width:6px;height:6px;border-radius:50%;background:var(--c-amber)"></span>
          Illustrative figures · statement structure from the FinTree GAAP ontology · click any bar to inspect the node
        </div>
      </div>`;
    }

    hierarchyHtml(v) {
      return `
      <div>
        <div style="display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:14px;flex-wrap:wrap">
          <div>
            <div style="font-family:'IBM Plex Mono',monospace;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink3)">Ontology · Icicle</div>
            <h1 style="margin:6px 0 0;font-size:22px;font-weight:800;letter-spacing:-.01em;color:var(--ink)">The full 234-node hierarchy</h1>
          </div>
          <nav aria-label="Breadcrumb" style="display:flex;align-items:center;gap:7px;flex-wrap:wrap">
            ${v.ic.breadcrumb.map((bc) => `
              <div style="display:flex;align-items:center;gap:7px">
                ${bc.sep ? `<span aria-hidden="true" style="color:var(--ink4);font-size:11px">/</span>` : ''}
                <button data-click="${this.reg(bc.onClick)}" style="font-family:'IBM Plex Mono',monospace;font-size:11.5px;color:${bc.color};background:none">${esc(bc.label)}</button>
              </div>`).join('')}
          </nav>
        </div>
        <div data-anim="icicle" style="position:relative;width:100%;height:620px;background:var(--panel);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);overflow:hidden">
          ${v.ic.cells.map((c) => `
            <button data-click="${this.reg(c.onClick)}" data-anim="cell" title="${esc(c.title)}" aria-label="${esc(c.title)}" style="${st(c.style)}">
              ${c.showLabel ? `<span style="font-size:11.5px;font-weight:600;color:${c.textColor};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block">${esc(c.label)}</span>${c.showCount ? `<span style="font-family:'IBM Plex Mono',monospace;font-size:9.5px;color:${c.subColor}">${esc(c.countLabel)}</span>` : ''}` : ''}
            </button>`).join('')}
        </div>
        <div style="margin-top:14px;font-family:'IBM Plex Mono',monospace;font-size:10.5px;color:var(--ink3)">Band height reflects relative subtree size (compressed for legibility) · click a band to zoom · breadcrumb to roll up · hover for full name</div>
      </div>`;
    }

    statementHtml(v) {
      return `
      <div>
        <div style="margin-bottom:14px">
          <div style="font-family:'IBM Plex Mono',monospace;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink3)">Statement order · Reg S-X 5-03</div>
          <h1 style="margin:6px 0 0;font-size:22px;font-weight:800;letter-spacing:-.01em;color:var(--ink)">Revenue to net income, line by line</h1>
          <div style="display:flex;align-items:center;gap:16px;margin-top:9px;font-family:'IBM Plex Mono',monospace;font-size:10.5px;color:var(--ink3)">
            <span style="display:flex;align-items:center;gap:6px"><span aria-hidden="true" style="color:var(--c-indigo);font-size:9px">▸</span>Category / subtotal</span>
            <span style="display:flex;align-items:center;gap:6px"><span aria-hidden="true" style="color:var(--ink4);font-size:9px">·</span>Line item</span>
          </div>
          ${v.overlay ? `<div style="margin-top:12px;display:flex;align-items:center;flex-wrap:wrap;gap:8px 15px;padding:10px 13px;background:color-mix(in srgb,var(--c-indigo) 10%,var(--panel));border:1px solid color-mix(in srgb,var(--c-indigo) 32%,var(--line));border-radius:12px">
            <span style="display:flex;align-items:center;gap:7px;font-weight:700;font-size:13px;color:var(--ink)"><span aria-hidden="true" style="width:8px;height:8px;border-radius:2px;background:var(--c-indigo)"></span>${esc(v.overlay.label)} overlay</span>
            <span style="font-family:'IBM Plex Mono',monospace;font-size:11px;color:var(--c-green)">✦ ${v.overlay.emph} emphasized</span>
            <span style="font-family:'IBM Plex Mono',monospace;font-size:11px;color:var(--c-red)">⊘ ${v.overlay.supp} suppressed</span>
            <span style="font-family:'IBM Plex Mono',monospace;font-size:11px;color:var(--ink3)">✎ ${v.overlay.rename} renamed</span>
            <span style="flex:1"></span>
            <button data-click="${this.reg(() => this.onIndustry({ target: { value: '' } }))}" style="font-family:'IBM Plex Mono',monospace;font-size:10.5px;color:var(--ink2);border:1px solid var(--line2);border-radius:7px;padding:4px 10px">Clear ✕</button>
          </div>` : ''}
        </div>
        <div style="display:flex;flex-direction:column;gap:9px">
          ${v.sections.map((s) => `
            <div data-anim="srow" style="opacity:${s.opacity};transition:opacity .2s">
              ${s.isInput ? `
                <div style="${st(s.cardStyle)}">
                  <div style="display:flex;align-items:center;gap:13px;padding:13px 15px">
                    <button data-click="${this.reg(s.onSelect)}" style="display:flex;align-items:center;gap:13px;flex:1;text-align:left;min-width:0">
                      <span aria-hidden="true" style="${st(s.iconStyle)}">${esc(s.icon)}</span>
                      <span style="display:flex;flex-direction:column;gap:3px;min-width:0">
                        <span style="font-weight:700;font-size:15.5px;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(s.label)}</span>
                        <span style="font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink3)">${esc(s.signLabel)}</span>
                      </span>
                    </button>
                    ${(s.emphN || s.suppN) ? `<span aria-hidden="true" style="display:flex;align-items:center;gap:9px;font-family:'IBM Plex Mono',monospace;font-size:10.5px;white-space:nowrap">${s.emphN ? `<span style="color:var(--c-green)">✦ ${s.emphN}</span>` : ''}${s.suppN ? `<span style="color:var(--c-red)">⊘ ${s.suppN}</span>` : ''}</span>` : ''}
                    <span style="font-family:'IBM Plex Mono',monospace;font-size:11.5px;color:var(--ink2);background:var(--panel2);border:1px solid var(--line);border-radius:20px;padding:4px 12px;white-space:nowrap">${s.count} nodes</span>
                    <button data-click="${this.reg(s.onToggle)}" aria-expanded="${s.open}" aria-label="Toggle ${esc(s.label)}" style="width:31px;height:31px;border-radius:9px;display:flex;align-items:center;justify-content:center;color:var(--ink2);background:var(--panel2);border:1px solid var(--line);font-size:12px;flex-shrink:0">${esc(s.caret)}</button>
                  </div>
                  ${s.open ? `
                    <div style="padding:3px 15px 15px;display:flex;flex-wrap:wrap;gap:7px">
                      ${s.chips.map((c) => `<button data-click="${this.reg(c.onClick)}" style="${st(c.style)}"><span aria-hidden="true" style="color:${c.markerColor};font-size:9px">${esc(c.marker)}</span>${esc(c.label)}</button>`).join('')}
                      ${s.hasMore ? `<button data-click="${this.reg(s.onMore)}" style="display:inline-flex;align-items:center;font-family:'IBM Plex Mono',monospace;font-size:11px;padding:6px 11px;border-radius:7px;background:transparent;border:1px dashed var(--line2);color:var(--ink3)">${esc(s.moreLabel)}</button>` : ''}
                    </div>` : ''}
                </div>` : ''}
              ${s.isSubtotal ? `
                <button data-click="${this.reg(s.onSelect)}" style="${st(s.rowStyle)}">
                  <span aria-hidden="true" style="${st(s.subIconStyle)}">=</span>
                  <span style="font-weight:700;font-size:15px;color:${s.labelColor}">${esc(s.label)}</span>
                  <span style="flex:1"></span>
                  <span style="font-family:'IBM Plex Mono',monospace;font-size:12px;font-style:italic;color:var(--ink3);white-space:nowrap">${esc(s.formula)}</span>
                </button>` : ''}
            </div>`).join('')}
        </div>
      </div>`;
    }

    /* ── render + animation ─────────────────────────────────────────── */
    render() {
      if (!this.root) return;
      const v = this.renderVals();

      // Preserve search focus + caret across the innerHTML swap.
      const ae = document.activeElement;
      const keepSearch = !!(ae && ae.id === 'ftSearch');
      const caret = keepSearch ? ae.selectionStart : null;

      this._handlers = [];
      this.root.className = 'ft-root';
      this.root.innerHTML = this.template(v);
      this.applyTheme();
      this.attach();

      if (keepSearch) {
        const s = this.root.querySelector('#ftSearch');
        if (s) { s.focus(); try { s.setSelectionRange(caret, caret); } catch (e) { /* noop */ } }
      }

      // Announce detail changes to screen readers via a live region that lives
      // OUTSIDE #app, so it survives the full innerHTML swap and actually fires.
      if (this._lann !== this.state.selectedId) {
        this._lann = this.state.selectedId;
        const live = document.getElementById('ftLive');
        if (live && v.hasSel) live.textContent = v.sel.label + ' — node detail loaded';
      }
      // Mobile: when the detail sheet is open it covers the page, so make every
      // other region inert — keyboard focus and assistive tech cannot reach the
      // controls behind the overlay (DOM is rebuilt each render, so this resets).
      if (this.isMobile() && this.state.panelOpen) {
        ['.ft-header', '.ft-content', '.ft-footer', '.ft-detail-toggle'].forEach((sel) => {
          const el = this.root.querySelector(sel);
          if (el) el.inert = true;
        });
      }
      // Mobile: move focus into the sheet when it opens, back to the toggle when
      // it closes (desktop keeps the panel persistently visible, so skip there).
      if (this._lpanel !== undefined && this._lpanel !== this.state.panelOpen && this.isMobile()) {
        const target = this.state.panelOpen
          ? this.root.querySelector('.ft-aside-close')
          : this.root.querySelector('.ft-detail-toggle');
        if (target) target.focus();
      }
      this._lpanel = this.state.panelOpen;

      this.animate();
    }

    animate() {
      const g = window.gsap, r = this.root;
      if (!r) return;
      const view = this.state.view;
      const viewChanged = this._lv !== view;

      if (!this._did || viewChanged) {
        this._did = true; this._lv = view;
        this.animateView();
        this._lsel = this.state.selectedId; this._lfoc = this.state.focusId; this._ldrill = this.state.drillKey;
        return;
      }
      if (!g || this.reduced()) {
        this._lsel = this.state.selectedId; this._lfoc = this.state.focusId; this._ldrill = this.state.drillKey;
        return;
      }
      if (this._lsel !== this.state.selectedId) {
        this._lsel = this.state.selectedId;
        const it = r.querySelectorAll('[data-anim="detail-item"]');
        if (it.length) g.fromTo(it, { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: .45, stagger: .04, ease: 'power2.out', overwrite: true, clearProps: 'opacity,transform' });
      }
      if (this._lfoc !== this.state.focusId && view === 'hierarchy') {
        this._lfoc = this.state.focusId;
        const w = r.querySelector('[data-anim="icicle"]');
        if (w) g.from(w, { opacity: 0, duration: .4, ease: 'power2.out', clearProps: 'opacity' });
      }
      if (this._ldrill !== this.state.drillKey && view === 'waterfall' && this.state.drillKey) {
        this._ldrill = this.state.drillKey;
        const seg = r.querySelectorAll('[data-anim="dseg"]');
        if (seg.length) g.fromTo(seg, { scaleX: 0 }, { scaleX: 1, transformOrigin: 'left center', duration: .5, stagger: .05, ease: 'power3.out', overwrite: true, clearProps: 'transform' });
      }
    }

    animateView() {
      const g = window.gsap, r = this.root, v = this.state.view;
      if (!r) return;
      if (!g || this.reduced()) { this.countUp(); return; }
      if (v === 'waterfall') {
        r.querySelectorAll('[data-anim="wbar"]').forEach((b) => {
          g.fromTo(b, { scaleY: 0 }, { scaleY: 1, transformOrigin: b.dataset.origin === 'top' ? 'center top' : 'center bottom', duration: .7, ease: 'power3.out', delay: .05 * (+b.dataset.i), overwrite: true, clearProps: 'transform' });
        });
        g.fromTo(r.querySelectorAll('[data-anim="wconn"]'), { scaleX: 0 }, { scaleX: 1, transformOrigin: 'left center', duration: .4, stagger: .06, delay: .18, ease: 'power2.out', overwrite: true, clearProps: 'transform' });
        g.fromTo(r.querySelectorAll('[data-anim="wlabel"]'), { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: .5, stagger: .05, delay: .25, ease: 'power2.out', overwrite: true, clearProps: 'opacity,transform' });
        this.countUp();
      } else if (v === 'hierarchy') {
        this._lfoc = this.state.focusId;
        const w = r.querySelector('[data-anim="icicle"]');
        if (w) g.from(w, { opacity: 0, y: 8, duration: .5, ease: 'power2.out', clearProps: 'opacity,transform' });
      } else {
        g.fromTo(r.querySelectorAll('[data-anim="srow"]'), { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: .5, stagger: .05, ease: 'power3.out', overwrite: true, clearProps: 'opacity,transform' });
      }
    }

    countUp() {
      const g = window.gsap, r = this.root; if (!r) return;
      r.querySelectorAll('[data-count]').forEach((el) => {
        const end = +el.dataset.count;
        const finalTxt = (el.dataset.prefix || '') + fmt(end) + (el.dataset.suffix || '');
        if (!g || this.reduced()) { el.textContent = finalTxt; return; }
        const o = { v: 0 };
        g.to(o, { v: end, duration: 1.1, ease: 'power2.out', delay: .25, onUpdate: () => { el.textContent = (el.dataset.prefix || '') + fmt(o.v) + (el.dataset.suffix || ''); }, onComplete: () => { el.textContent = finalTxt; } });
      });
    }
  }

  /* ── Boot ─────────────────────────────────────────────────────────── */
  function boot() {
    const el = document.getElementById('app');
    if (!el) return;
    if (!window.FINTREE_DATA) {
      el.innerHTML = '<div style="padding:48px 24px;font-family:system-ui,sans-serif;color:#8892a0">FinTree data failed to load. Ensure <code>tree-data.js</code> is present.</div>';
      return;
    }
    const PL = buildPL(window.FINTREE_DATA);
    const app = new Explorer(el, PL, { startView: 'waterfall', startTheme: 'dark', showFooter: true });
    app.mount();
    window.__ftApp = app; // expose for debugging
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
